def solve(expr):
    def operate(op, b, a):
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            return a // b

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def eval_expr(tokens):
        def eval_operand():
            num = ''
            while tokens and (tokens[0].isdigit() or tokens[0] == '-'):
                num += tokens.pop(0)
                if not tokens or not tokens[0].isdigit():
                    break
            return int(num)

        ops = []
        vals = []
        while tokens:
            token = tokens.pop(0)
            if token.isdigit() or token == '-':
                vals.append(eval_operand())
            elif token == '(':
                ops.append(token)
            elif token == ')':
                while ops and ops[-1] != '(':
                    vals.append(operate(ops.pop(), vals.pop(), vals.pop()))
                ops.pop()  # pop '('
            else:
                while (ops and precedence(ops[-1]) >= precedence(token)):
                    vals.append(operate(ops.pop(), vals.pop(), vals.pop()))
                ops.append(token)
        while ops:
            vals.append(operate(ops.pop(), vals.pop(), vals.pop()))
        return vals[0]

    return eval_expr(list(expr.replace(' ', '')))

# Example usage:
# print(solve("3+5/2"))
# print(solve("1-2*3/4+5"))
